  parameters: { sourceCode: 'import AmazonM from \'@semcore/icon/color/Amazon/m\';\nimport { ButtonLink } from \'@semcore/ui/button\';\nimport type { DataTableSort } from \'@semcore/ui/data-table\';\nimport { DataTable } from \'@semcore/ui/data-table\';\nimport { Text } from \'@semcore/ui/typography\';\nimport React from \'react\';\n\ntype SortableColumn = Exclude<keyof typeof data[0], \'keyword\'>;\n\nconst Demo = () => {\n  const [sort, setSort] = React.useState<DataTableSort<keyof typeof data[0]>>([\'kd\', \'desc\']);\n  const sortedData = React.useMemo(\n    () =>\n      [...data].sort((aRow, bRow) => {\n        const [prop, sortDirection] = sort;\n        const a = aRow[prop as SortableColumn];\n        const b = bRow[prop as SortableColumn];\n        if (a === b) return 0;\n        if (sortDirection === \'asc\') return a > b ? 1 : -1;\n        else return a > b ? -1 : 1;\n      }),\n    [sort],\n  );\n  const numberFormat = React.useMemo(() => new Intl.NumberFormat(\'en-US\'), []);\n  const currencyFormat = React.useMemo(\n    () => new Intl.NumberFormat(\'en-US\', { currency: \'USD\', style: \'currency\' }),\n    [],\n  );\n\n  return (\n    <DataTable\n      virtualScroll\n      aria-label=\'Borders\'\n      defaultGridTemplateColumnWidth=\'1fr\'\n      sort={sort}\n      onSortChange={setSort}\n      h=\'100%\'\n      data={sortedData}\n      columns={[\n        {\n          name: \'organicSessions\',\n          children: \'Organic Sessions\',\n          borders: \'left\',\n          columns: [\n            {\n              name: \'kd\',\n              sortable: true,\n              gtcWidth: \'100px\',\n              children: (\n                <Text>\n                  Kd Organic Sessions Organic Sessions\n                  <ButtonLink addonLeft={AmazonM} title=\'AmazonM non interactive\' color=\'icon-secondary-neutral\' />\n                </Text>\n              ),\n            },\n            { name: \'cpc\', children: \'CPC\', sortable: true },\n            { name: \'vol\', children: \'Vol.\' },\n          ],\n        },\n        { name: \'keyword\', children: \'Keyword\', sortable: true },\n        {\n          name: \'organicSessions2\',\n          children: \'Organic Sessions Organic Sessions Organic SessionsOrganic Sessions Organic Sessions Organic Sessions\',\n          borders: \'both\',\n          columns: [\n            {\n              name: \'kd2\',\n              sortable: true,\n              gtcWidth: \'100px\',\n              children: (\n                <>\n                  <Text ellipsis={true}>Kd Organic Sessions</Text>\n                  <ButtonLink addonLeft={AmazonM} title=\'AmazonM non interactive\' color=\'icon-secondary-neutral\' />\n                </>\n              ),\n            },\n            { name: \'cpc2\', children: \'CPC\', sortable: true },\n            { name: \'vol\', children: \'Vol.\' },\n          ],\n        },\n        { name: \'other\', children: \'Other\' },\n        {\n          name: \'organicSessions3\',\n          children: \'Organic Sessions\',\n          borders: \'right\',\n          columns: [\n            {\n              name: \'kd\',\n              children: (\n                <>\n                  <ButtonLink addonLeft={AmazonM} title=\'AmazonM non interactive\' color=\'icon-secondary-neutral\' />\n                  <ButtonLink addonLeft={AmazonM} title=\'AmazonM non interactive\' color=\'icon-secondary-neutral\' />\n                </>\n              ),\n            },\n            { name: \'cpc\', children: \'CPC\' },\n            { name: \'vol\', children: \'Vol.\' },\n          ],\n        },\n        { name: \'other2\', children: \'Other\' },\n      ]}\n\n    />\n  );\n};\n\nconst data = [\n  {\n    keyword: \'ebay buy\',\n    kd: \'77.8\',\n    kd2: \'77.8\',\n    cpc: \'1.25\',\n    vol: \'32,500,000\',\n    other: \'ebay buy\',\n  },\n  {\n    keyword: \'www.ebay.com\',\n    kd: \'11.2\',\n    kd2: \'77.8\',\n    cpc: \'3.4\',\n    vol: \'65,457,920\',\n    other: \'ebay buy\',\n  },\n  {\n    keyword: \'www.ebay.com\',\n    kd: \'10\',\n    kd2: \'77.8\',\n    cpc: \'0.65\',\n    vol: \'47,354,640\',\n    other: \'ebay buy\',\n  },\n  {\n    keyword: \'ebay buy\',\n    kd: \'-\',\n    kd2: \'77.8\',\n    cpc: \'0\',\n    vol: \'2,456,789\',\n    other: \'ebay buy\',\n  },\n  {\n    keyword: \'ebay buy\',\n    kd: \'75.89\',\n    cpc: \'0\',\n    kd2: \'77.8\',\n    vol: \'21,644,290\',\n    other: \'ebay buy\',\n  },\n  {\n    keyword: \'ebay buy\',\n    kd: \'77.8\',\n    cpc: \'1.25\',\n    kd2: \'77.8\',\n    vol: \'32,500,000\',\n    other: \'ebay buy\',\n  },\n  {\n    keyword: \'www.ebay.com\',\n    kd: \'11.2\',\n    cpc: \'3.4\',\n    kd2: \'77.8\',\n    vol: \'65,457,920\',\n    other: \'ebay buy\',\n  },\n  {\n    keyword: \'www.ebay.com\',\n    kd: \'10\',\n    cpc: \'0.65\',\n    kd2: \'77.8\',\n    vol: \'47,354,640\',\n    other: \'ebay buy\',\n  },\n  {\n    keyword: \'ebay buy\',\n    kd: \'-\',\n    cpc: \'0\',\n    kd2: \'77.8\',\n    vol: \'2,456,789\',\n    other: \'ebay buy\',\n  },\n  {\n    keyword: \'ebay buy\',\n    kd: \'75.89\',\n    cpc: \'0\',\n    kd2: \'77.8\',\n    vol: \'21,644,290\',\n    other: \'ebay buy\',\n  },\n];\n\nexport default Demo;\n' },
