export const VirtualScrollControls: StoryObj<VirtualScrollControlsProps> = {
  render: VirtualScrollControlsExample,
  args: virtualScrollControlsDefaultProps,
  argTypes: {
    mode: {
      control: 'radio',
      options: ['boolean', 'aproxRowsOnPage', 'rowHeight', 'rowsBufferOnly'] satisfies VirtualScrollControlsProps['mode'][],
      description: 'Selects the virtualScroll mode. ' +
        '`boolean` - true, default buffers. ' +
        '`aproxRowsOnPage` - auto row height, configurable buffer + page estimate. ' +
        '`rowHeight` - fixed row height, configurable buffer + page estimate ' +
        '`rowsBufferOnly` - only rowsBuffer set, no rowHeight, no aproxRowsOnPage (uses defaults for page estimate).',
    },
    useCustomBuffer: {
      control: 'boolean',
      description: 'When false — rowsBuffer is omitted, component uses default (20).',
      if: { arg: 'mode', neq: 'boolean' },
    },
    rowsBuffer: {
      control: { type: 'number', min: 1, max: 100 },
      description: 'Pre-rendered rows above/below viewport. Only applied when `useCustomBuffer` is true.',
      if: { arg: 'useCustomBuffer', truthy: true },
    },
    aproxRowsOnPage: {
      control: { type: 'number', min: 1, max: 100 },
      description: 'Estimated rows per page for scroll position calculation. Only used in `aproxRowsOnPage` mode.',
      if: { arg: 'mode', eq: 'aproxRowsOnPage' },
    },
    rowHeight: {
      control: { type: 'number', min: 20, max: 200 },
      description: 'Fixed row height in px (required in `rowHeight` mode). ' +
        'Mutually exclusive with `aproxRowsOnPage`. ' +
        'If `rowsBuffer` is not set, defaults to 20.',
      if: { arg: 'mode', eq: 'rowHeight' },
    },
  },
  parameters: { sourceCode: 'import { DataTable } from \'@semcore/ui/data-table\';\nimport React from \'react\';\n\nexport type VirtualScrollMode = \'boolean\' | \'aproxRowsOnPage\' | \'rowHeight\' | \'rowsBufferOnly\';\n\nexport type VirtualScrollControlsProps = {\n  mode: VirtualScrollMode;\n  useCustomBuffer: boolean;\n  rowsBuffer: number;\n  aproxRowsOnPage: number;\n  rowHeight: number;\n};\n\nexport const virtualScrollControlsDefaultProps: VirtualScrollControlsProps = {\n  mode: \'aproxRowsOnPage\' as VirtualScrollMode,\n  useCustomBuffer: true,\n  rowsBuffer: 20,\n  aproxRowsOnPage: 20,\n  rowHeight: 45,\n};\n\nconst keywords = [\'ebay buy\', \'www.ebay.com\', \'ebay buy\'];\nconst kd = [\'77.8\', \'10\', \'11.2\', \'-\', \'75.89\'];\nconst cpc = [\'$3.4\', \'$0.65\', \'$1.25\', \'$0\', \'$0\'];\nconst vol = [\'32,500,000\', \'65,457,920\', \'47,354,640\', \'n/a\', \'21,644,290\'];\n\nconst data = Array(500)\n  .fill(0)\n  .map((_, index) => ({\n    id: `#${index + 1}`,\n    keyword: keywords[index % keywords.length],\n    kd: kd[index % kd.length],\n    cpc: cpc[index % cpc.length],\n    vol: vol[index % vol.length],\n  }));\n\nconst Demo = ({\n  mode,\n  useCustomBuffer,\n  rowsBuffer,\n  aproxRowsOnPage,\n  rowHeight,\n}: VirtualScrollControlsProps = virtualScrollControlsDefaultProps) => {\n  const buffer = useCustomBuffer ? rowsBuffer : undefined;\n\n  const virtualScroll =\n    mode === \'boolean\'\n      ? true\n      : mode === \'rowHeight\'\n        ? (buffer !== undefined ? { rowHeight, rowsBuffer: buffer } : { rowHeight })\n        : mode === \'rowsBufferOnly\'\n          ? { rowsBuffer: buffer }\n          : (buffer !== undefined ? { rowsBuffer: buffer, aproxRowsOnPage } : { aproxRowsOnPage });\n\n  return (\n    <DataTable\n      data={data}\n      totalRows={data.length}\n      aria-label=\'Virtual scroll controls\'\n      h={400}\n      virtualScroll={virtualScroll}\n      headerProps={{ sticky: true }}\n      columns={[\n        { name: \'id\', children: \'ID\', gtcWidth: \'60px\' },\n        { name: \'keyword\', children: \'Keyword\', gtcWidth: \'200px\' },\n        { name: \'kd\', children: \'KD %\' },\n        { name: \'cpc\', children: \'CPC\' },\n        { name: \'vol\', children: \'Vol.\' },\n      ]}\n    />\n  );\n};\n\nexport default Demo;\n' },
};
